import 'package:flutter/material.dart';
import '../../models/delivery_model.dart';
import 'executive_repository.dart';

class RaiseEscalationScreen extends StatefulWidget { final DeliveryModel delivery; final ExecutiveRepository repository; const RaiseEscalationScreen({super.key, required this.delivery, required this.repository}); @override State<RaiseEscalationScreen> createState() => _RaiseEscalationScreenState(); }
class _RaiseEscalationScreenState extends State<RaiseEscalationScreen> { final _reason = TextEditingController(); final _description = TextEditingController(); String _priority = 'MEDIUM'; String? _error; bool _busy = false; @override void dispose() { _reason.dispose(); _description.dispose(); super.dispose(); } Future<void> _submit() async { if (_reason.text.trim().isEmpty) { setState(() => _error = 'Enter a short reason.'); return; } setState(() { _busy = true; _error = null; }); try { await widget.repository.createEscalation(deliveryId: widget.delivery.id, reason: _reason.text.trim(), description: _description.text.trim(), priority: _priority); if (mounted) { await showDialog<void>(context: context, builder: (_) => AlertDialog(title: const Text('Escalation raised'), content: const Text('Your escalation was saved for review.'), actions: [TextButton(onPressed: () => Navigator.pop(context), child: const Text('Done'))])); if (mounted) Navigator.pop(context); } } catch (e) { if (mounted) setState(() => _error = e.toString()); } finally { if (mounted) setState(() => _busy = false); } } @override Widget build(BuildContext context) => Scaffold(appBar: AppBar(title: const Text('Raise escalation')), body: ListView(padding: const EdgeInsets.all(20), children: [TextField(controller: _reason, maxLength: 120, decoration: const InputDecoration(labelText: 'Reason *')), TextField(controller: _description, maxLines: 4, maxLength: 500, decoration: const InputDecoration(labelText: 'Description (optional)')), DropdownButtonFormField<String>(value: _priority, decoration: const InputDecoration(labelText: 'Priority'), items: escalationPriorities.map((priority) => DropdownMenuItem(value: priority, child: Text(priority[0] + priority.substring(1).toLowerCase()))).toList(), onChanged: _busy ? null : (value) => setState(() => _priority = value ?? 'MEDIUM')), if (_error != null) Text(_error!, style: TextStyle(color: Theme.of(context).colorScheme.error)), const SizedBox(height: 20), SizedBox(height: 52, child: FilledButton(onPressed: _busy ? null : _submit, child: _busy ? const CircularProgressIndicator() : const Text('Submit escalation')))])); }